import{bQ as d,aL as a,u as e,G as o}from"./chunks/framework.CNL6o8_w.js";const T=JSON.parse('{"title":"AT 命令集 (at_in / at_out)","description":"","frontmatter":{},"headers":[],"relativePath":"lightsmart/gateway/at-commands.md","filePath":"lightsmart/gateway/at-commands.md"}'),c={name:"lightsmart/gateway/at-commands.md"};function s(i,t,n,l,r,p){return a(),e("div",null,[...t[0]||(t[0]=[o(`<h1 id="at-命令集-at-in-at-out" tabindex="-1">AT 命令集 (at_in / at_out) <a class="header-anchor" href="#at-命令集-at-in-at-out" aria-label="Permalink to &quot;AT 命令集 (at_in / at_out)&quot;">​</a></h1><p>hapi 通过 <code>{topicL1}/{mq_id}/at_in</code> 主题向网关下发 AT 命令，网关通过 <code>{topicL1}/{mq_id}/at_out</code> 上报响应。</p><h2 id="主题" tabindex="-1">主题 <a class="header-anchor" href="#主题" aria-label="Permalink to &quot;主题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>方向</th><th>格式</th><th>说明</th></tr></thead><tbody><tr><td><code>{topicL1}/{mq_id}/at_in</code></td><td>hapi → 网关</td><td>AT 命令字符串</td><td>串口指令下发</td></tr><tr><td><code>{topicL1}/{mq_id}/at_out</code></td><td>网关 → hapi</td><td>字符串</td><td>AT 命令响应</td></tr></tbody></table><h2 id="消息格式" tabindex="-1">消息格式 <a class="header-anchor" href="#消息格式" aria-label="Permalink to &quot;消息格式&quot;">​</a></h2><p>AT 命令以纯文本字符串发送，以 <code>\\r\\n</code> 结尾：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>at+restore\\r\\n</span></span></code></pre></div><h2 id="at-命令列表" tabindex="-1">AT 命令列表 <a class="header-anchor" href="#at-命令列表" aria-label="Permalink to &quot;AT 命令列表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>参数</th><th>响应</th><th>说明</th></tr></thead><tbody><tr><td><code>AT</code></td><td>无</td><td><code>OK</code></td><td>测试命令</td></tr><tr><td><code>AT+CWMODE</code></td><td><code>&lt;mode&gt;</code></td><td><code>OK</code> / <code>ERROR</code></td><td>WiFi 模式（1=STA, 2=AP）</td></tr><tr><td><code>AT+CWJAP</code></td><td><code>&lt;ssid&gt;,&lt;password&gt;</code></td><td><code>+CWJAP:1</code> / <code>+CWJAP:0</code></td><td>连接 AP</td></tr><tr><td><code>AT+CIPSTA</code></td><td>无</td><td><code>+CIPSTA:ip:&quot;x.x.x.x&quot;</code></td><td>查询 IP 地址</td></tr><tr><td><code>AT+CIPSTAMAC</code></td><td>无</td><td><code>+CIPSTAMAC:&quot;xx:xx:...&quot;</code></td><td>查询 MAC 地址</td></tr><tr><td><code>AT+CPCODE</code></td><td><code>&lt;code&gt;</code> / 无</td><td><code>OK</code> / <code>+CPCODE:&quot;...&quot;</code></td><td>设置/查询模块编码</td></tr><tr><td><code>AT+MQTTSTART</code></td><td>无</td><td><code>OK</code></td><td>启动 MQTT 连接</td></tr><tr><td><code>AT+BLE_PAIR</code></td><td><code>&lt;0/1&gt;</code></td><td><code>OK</code></td><td>BLE 配对控制（0=停止, 1=开始）</td></tr><tr><td><code>AT+RSSI</code></td><td>无</td><td><code>+RSSI:&lt;dBm&gt;</code></td><td>查询 WiFi 信号强度</td></tr><tr><td><code>AT+RESTORE</code></td><td>无</td><td><code>OK</code></td><td>恢复出厂设置</td></tr><tr><td><code>AT+FUNC</code></td><td><code>&lt;sn&gt;</code> / 无</td><td><code>OK</code> / <code>+FUNC:&quot;...&quot;</code></td><td>设置/查询客户序列号</td></tr><tr><td><code>AT+GET_SCAN</code></td><td>无</td><td><code>&lt;ssid&gt;,&lt;bssid&gt;,&lt;rssi&gt;,&lt;ch&gt;,&lt;auth&gt;</code></td><td>WiFi 扫描结果</td></tr><tr><td><code>AT+NODE</code></td><td><code>meshkey=&lt;hex&gt;</code> / 无</td><td><code>+NODE:meshkey=&quot;...&quot;</code></td><td>节点/meshkey 管理</td></tr></tbody></table><h2 id="常用场景" tabindex="-1">常用场景 <a class="header-anchor" href="#常用场景" aria-label="Permalink to &quot;常用场景&quot;">​</a></h2><h3 id="恢复出厂设置" tabindex="-1">恢复出厂设置 <a class="header-anchor" href="#恢复出厂设置" aria-label="Permalink to &quot;恢复出厂设置&quot;">​</a></h3><p>hapi 调用 <code>resetGateway(deviceId)</code> 下发 <code>at+restore</code> 命令，网关恢复出厂后自动重启。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Topic: {topicL1}/{mq_id}/at_in</span></span>
<span class="line"><span>Payload: at+restore\\r\\n</span></span></code></pre></div><h3 id="wifi-配网" tabindex="-1">WiFi 配网 <a class="header-anchor" href="#wifi-配网" aria-label="Permalink to &quot;WiFi 配网&quot;">​</a></h3><p>配网流程中，小程序通过 ztUtil SDK 经 BLE 向网关发送 AT 命令配置 WiFi：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CWMODE=1          ← 设置为 STA 模式</span></span>
<span class="line"><span>AT+CWJAP=&quot;ssid&quot;,&quot;psk&quot; ← 连接 WiFi</span></span>
<span class="line"><span>AT+MQTTSTART          ← 启动 MQTT</span></span></code></pre></div><h3 id="查询设备信息" tabindex="-1">查询设备信息 <a class="header-anchor" href="#查询设备信息" aria-label="Permalink to &quot;查询设备信息&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AT+CIPSTA       → 查询 IP</span></span>
<span class="line"><span>AT+CIPSTAMAC    → 查询 MAC</span></span>
<span class="line"><span>AT+RSSI         → 查询信号强度</span></span>
<span class="line"><span>AT+FUNC         → 查询序列号</span></span></code></pre></div><h2 id="at-命令处理流程" tabindex="-1">AT 命令处理流程 <a class="header-anchor" href="#at-命令处理流程" aria-label="Permalink to &quot;AT 命令处理流程&quot;">​</a></h2><p>网关固件中 <code>shell_task</code> 负责处理 AT 命令：</p><ol><li>UART0 逐字节读取 → 行缓冲</li><li>遇到 <code>\\r\\n</code> 触发 AT 命令解析</li><li>匹配命令前缀 → 分发到对应处理函数</li><li>执行操作 → 返回响应字符串</li></ol><blockquote><p>AT 命令同时支持 UART 串口直连和 MQTT 远程下发两种方式。MQTT 下发的 AT 命令通过 <code>at_in</code> 主题接收，响应通过 <code>at_out</code> 主题上报。<code>at_out</code> 的发布通过事件队列异步执行，避免阻塞 UART 接收。</p></blockquote>`,22)])])}const u=d(c,[["render",s]]);export{T as __pageData,u as default};
